<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use PDO;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Infrastructure\Driven\TokenRevocationSqlAdapter;
use Civi\Lughauth\Shared\AppConfig;
use PHPUnit\Framework\TestCase;

final class TokenRevocationSqlAdapterTest extends TestCase
{
    private const string TENANT = 'tenant-refresh-race';
    private const int CONTENDERS = 8;
    private const int ROUNDS = 5;

    /** Each contender is a separate PHP process with its own connection, released at the same instant. */
    private const string CONTENDER = <<<'PHP'
        <?php
        [, $autoload, $jti, $tenant, $startAt] = $argv;
        require $autoload;
        try {
            $config = new Civi\Lughauth\Shared\AppConfig();
            $pdo = new PDO($config->get('database.url'), $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
            $store = new Civi\Lughauth\Features\OAuth\TokenSecurity\Infrastructure\Driven\TokenRevocationSqlAdapter($pdo);
            $pdo->query('SELECT 1');
            time_sleep_until((float) $startAt);
            echo $store->consumeJti($jti, $tenant, 'refresh', new DateTimeImmutable('+1 hour')) ? 'won' : 'lost';
        } catch (Throwable $error) {
            echo 'error: ', $error->getMessage();
        }
        PHP;

    /** @var string[] */
    private array $jtis = [];

    /** @var string[] */
    private array $families = [];

    protected function tearDown(): void
    {
        if ($this->jtis === [] && $this->families === []) {
            return;
        }
        $pdo = $this->connect();
        $deleteJti = $pdo->prepare('DELETE FROM _oauth_revoked_jti WHERE jti = :jti');
        foreach ($this->jtis as $jti) {
            $deleteJti->execute(['jti' => $jti]);
        }
        $deleteFamily = $pdo->prepare('DELETE FROM _oauth_revoked_refresh_family WHERE family_id = :family');
        foreach ($this->families as $family) {
            $deleteFamily->execute(['family' => $family]);
        }
    }

    public function testConcurrentConsumptionOfOneRefreshTokenHasASingleWinner(): void
    {
        $this->connect();
        for ($round = 0; $round < self::ROUNDS; $round++) {
            $jti = $this->jtis[] = Uuid::uuid4()->toString();

            $outcomes = array_count_values($this->race($jti));

            ksort($outcomes);
            self::assertSame(['lost' => self::CONTENDERS - 1, 'won' => 1], $outcomes, 'round ' . $round);
        }
    }

    public function testConsumedOrRevokedJtiCannotBeConsumedAgain(): void
    {
        $store = new TokenRevocationSqlAdapter($this->connect());
        $consumed = $this->jtis[] = Uuid::uuid4()->toString();
        $revoked = $this->jtis[] = Uuid::uuid4()->toString();
        $expiresAt = new \DateTimeImmutable('+1 hour');

        self::assertTrue($store->consumeJti($consumed, self::TENANT, 'refresh', $expiresAt));
        self::assertFalse($store->consumeJti($consumed, self::TENANT, 'refresh', $expiresAt));
        self::assertTrue($store->isRevoked($consumed, self::TENANT));

        $store->revokeJti($revoked, self::TENANT, 'refresh', $expiresAt);
        self::assertFalse($store->consumeJti($revoked, self::TENANT, 'refresh', $expiresAt));
    }

    public function testFamilyRevocationIsIdempotentAndScopedToTenant(): void
    {
        $store = new TokenRevocationSqlAdapter($this->connect());
        $family = $this->families[] = Uuid::uuid4()->toString();
        $expiresAt = new \DateTimeImmutable('+1 hour');

        self::assertFalse($store->isFamilyRevoked($family, self::TENANT));
        $store->revokeFamily($family, self::TENANT, $expiresAt);
        $store->revokeFamily($family, self::TENANT, $expiresAt);

        self::assertTrue($store->isFamilyRevoked($family, self::TENANT));
        self::assertFalse($store->isFamilyRevoked($family, 'other-tenant'));
    }

    /** @return string[] outcome of every contender: "won", "lost" or "error: ..." */
    private function race(string $jti): array
    {
        $autoload = dirname(__DIR__, 4) . '/vendor/autoload.php';
        // Leave time for every process to boot and connect before the shared start instant.
        $startAt = sprintf('%.6F', microtime(true) + 1.5);
        $processes = [];
        for ($i = 0; $i < self::CONTENDERS; $i++) {
            $process = proc_open(
                [PHP_BINARY, '--', $autoload, $jti, self::TENANT, $startAt],
                [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
                $pipes
            );
            self::assertIsResource($process);
            fwrite($pipes[0], self::CONTENDER);
            fclose($pipes[0]);
            $processes[] = [$process, $pipes];
        }

        $outcomes = [];
        foreach ($processes as [$process, $pipes]) {
            $outcomes[] = trim((string) stream_get_contents($pipes[1])) ?: trim((string) stream_get_contents($pipes[2]));
            fclose($pipes[1]);
            fclose($pipes[2]);
            proc_close($process);
        }
        return $outcomes;
    }

    private function connect(): PDO
    {
        $config = new AppConfig();
        $dsn = $config->get('database.url');
        if (!is_string($dsn) || !str_starts_with($dsn, 'mysql:')) {
            $this->markTestSkipped('MySQL integration database not configured');
        }

        try {
            $pdo = new PDO($dsn, $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
        } catch (\PDOException) {
            $this->markTestSkipped('MySQL integration database not available');
        }
        if ($pdo->query("SHOW TABLES LIKE '_oauth_revoked_refresh_family'")->rowCount() === 0) {
            $this->markTestSkipped('Migration 20261016200000 (_oauth_revoked_refresh_family) not applied');
        }
        return $pdo;
    }
}
